function hexToRgb(h){
  h=String(h||'').replace('#','');
  if(h.length===3) h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
  var n=parseInt(h,16);
  return [(n>>16)&255,(n>>8)&255,n&255];
}
function rgbToHex(r,g,b){
  function c(x){ x=Math.max(0,Math.min(255,Math.round(x))); return ('0'+x.toString(16)).slice(-2); }
  return '#'+c(r)+c(g)+c(b);
}
// pixels: array of [r,g,b]; returns per-channel grayscale arrays
function splitChannels(pixels){
  var r=[],g=[],b=[];
  for(var i=0;i<pixels.length;i++){ r.push(pixels[i][0]); g.push(pixels[i][1]); b.push(pixels[i][2]); }
  return {r:r,g:g,b:b};
}
function composeChannels(r,g,b){
  var n=Math.min(r.length,g.length,b.length);
  var out=new Array(n);
  for(var i=0;i<n;i++){ out[i]=[r[i],g[i],b[i]]; }
  return out;
}
// 通道互换：map = {r:'g', g:'b', b:'r'} 表示新R=旧G等
function swapChannels(pixels, map){
  map = map || {r:'b',g:'g',b:'r'};
  return pixels.map(function(p){
    var o={r:p[0],g:p[1],b:p[2]};
    return [ o[map.r], o[map.g], o[map.b] ];
  });
}
function toGray(pixels, mode){
  mode=mode||'lum';
  return pixels.map(function(p){
    var v = mode==='avg' ? (p[0]+p[1]+p[2])/3 : 0.299*p[0]+0.587*p[1]+0.114*p[2];
    return [v,v,v];
  });
}

var EXPORTS={hexToRgb:hexToRgb,rgbToHex:rgbToHex,splitChannels:splitChannels,composeChannels:composeChannels,swapChannels:swapChannels,toGray:toGray};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ChannelForgePure = EXPORTS; }
